"use client";

import { useEffect, useId, useRef } from "react";
import { cn } from "@/components/ui";

/**
 * NVX mascot: the pink blob logo as a living character.
 * Layers: eyeless body image (public/brand/mascot-body-*.png|webp, generated by
 * scripts/gen-brand-assets.py) + two glossy capsule eyes drawn in SVG on the same 1024 grid,
 * so the eyes can blink and look around. Animations are pure CSS (globals.css, `.nvx-mascot*`)
 * and stop under prefers-reduced-motion. `interactive` adds cursor-following eyes (fine pointers
 * only) and a squishy bounce on hover/click. No dependencies.
 */

// Same geometry as EYES in scripts/gen-brand-assets.py (centre, semi-axes, tilt from vertical).
export const MASCOT_EYES = [
  { cx: 575.6, cy: 406.3, rx: 60, ry: 136, tilt: -21 },
  { cx: 802.1, cy: 341.3, rx: 59, ry: 134, tilt: -22 },
] as const;
const LOOK_RANGE = 16; // max eye travel in 1024-grid units

export interface MascotProps {
  /** Rendered size in CSS px. */
  size: number;
  /** Eyes follow the cursor and the body squishes on hover/click. */
  interactive?: boolean;
  /** Accessible name; omit for decorative use (aria-hidden). */
  label?: string;
  className?: string;
}

export function Mascot({ size, interactive = false, label, className }: MascotProps) {
  const uid = useId().replace(/:/g, "");
  const root = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    const el = root.current;
    if (!el || !interactive) return;
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)");
    const fine = window.matchMedia("(hover: hover) and (pointer: fine)");

    let frame = 0;
    let px = 0;
    let py = 0;
    const apply = () => {
      frame = 0;
      const r = el.getBoundingClientRect();
      const dx = px - (r.left + r.width / 2);
      const dy = py - (r.top + r.height / 2);
      const dist = Math.hypot(dx, dy) || 1;
      const reach = Math.min(1, dist / 400); // ease in over the first 400px
      el.style.setProperty("--nvx-look-x", ((dx / dist) * reach * LOOK_RANGE).toFixed(1));
      el.style.setProperty("--nvx-look-y", ((dy / dist) * reach * LOOK_RANGE).toFixed(1));
    };
    const onMove = (e: PointerEvent) => {
      if (reduced.matches || !fine.matches || e.pointerType !== "mouse") return;
      px = e.clientX;
      py = e.clientY;
      if (!frame) frame = requestAnimationFrame(apply);
    };
    const reset = () => {
      el.style.setProperty("--nvx-look-x", "0");
      el.style.setProperty("--nvx-look-y", "0");
    };
    const squish = () => {
      if (reduced.matches) return;
      el.classList.remove("is-squish");
      void el.offsetWidth; // restart the animation
      el.classList.add("is-squish");
    };
    const endSquish = (e: AnimationEvent) => {
      if (e.animationName === "nvx-mascot-squish") el.classList.remove("is-squish");
    };

    window.addEventListener("pointermove", onMove, { passive: true });
    document.documentElement.addEventListener("pointerleave", reset);
    el.addEventListener("pointerenter", squish);
    el.addEventListener("click", squish);
    el.addEventListener("animationend", endSquish);
    return () => {
      if (frame) cancelAnimationFrame(frame);
      window.removeEventListener("pointermove", onMove);
      document.documentElement.removeEventListener("pointerleave", reset);
      el.removeEventListener("pointerenter", squish);
      el.removeEventListener("click", squish);
      el.removeEventListener("animationend", endSquish);
    };
  }, [interactive]);

  const small = size <= 48;
  const src = small ? "/brand/mascot-body-64.webp" : "/brand/mascot-body-256.png";
  const srcSet = small
    ? "/brand/mascot-body-64.webp 2x, /brand/mascot-body-96.webp 3x"
    : "/brand/mascot-body-256.png 1x, /brand/mascot-body-512.png 2x";

  return (
    <span
      ref={root}
      className={cn("nvx-mascot", interactive && "nvx-mascot--interactive", className)}
      style={{ width: size, height: size }}
      data-testid="nvx-mascot"
      {...(label ? { role: "img", "aria-label": label } : { "aria-hidden": true })}
    >
      <span className="nvx-mascot-float">
        <span className="nvx-mascot-body">
          {/* eslint-disable-next-line @next/next/no-img-element -- tiny static brand asset, no optimizer needed */}
          <img src={src} srcSet={srcSet} width={size} height={size} alt="" draggable={false} decoding="async" />
          <svg viewBox="0 0 1024 1024" className="nvx-mascot-eyes" aria-hidden focusable="false">
            <defs>
              <radialGradient id={`${uid}-iris`} cx="0.45" cy="0.55" r="0.6">
                <stop offset="0" stopColor="#0b0408" />
                <stop offset="0.72" stopColor="#14060f" />
                <stop offset="1" stopColor="#3d0d30" />
              </radialGradient>
              <radialGradient id={`${uid}-shine`} cx="0.45" cy="0.3" r="0.75">
                <stop offset="0" stopColor="#ffffff" />
                <stop offset="0.45" stopColor="#ffd0ef" />
                <stop offset="1" stopColor="#ff4fc4" stopOpacity="0.85" />
              </radialGradient>
            </defs>
            <g className="nvx-mascot-look">
              {MASCOT_EYES.map((e, i) => {
                const { rx, ry } = e;
                const x0 = rx * 0.14; // highlight sits slightly right of the eye axis
                const shine = `M ${x0 - rx * 0.44} ${-ry * 0.58} C ${x0 - rx * 0.46} ${-ry * 0.9} ${x0 + rx * 0.44} ${-ry * 0.92} ${x0 + rx * 0.42} ${-ry * 0.6} L ${x0 + rx * 0.2} ${-ry * 0.02} Q ${x0 + rx * 0.04} ${ry * 0.08} ${x0 - rx * 0.1} ${-ry * 0.08} Z`;
                return (
                  <g key={i} transform={`translate(${e.cx} ${e.cy}) rotate(${e.tilt})`}>
                    <g className="nvx-mascot-eye">
                      {/* dark-magenta socket, near-black glossy eye with a plum rim, teardrop shine, edge glints */}
                      <rect x={-rx - 10} y={-ry - 10} width={(rx + 10) * 2} height={(ry + 10) * 2} rx={rx + 10} fill="#b5067f" />
                      <rect x={-rx} y={-ry} width={rx * 2} height={ry * 2} rx={rx} fill={`url(#${uid}-iris)`} stroke="#2a0820" strokeWidth="4" />
                      <path d={shine} fill={`url(#${uid}-shine)`} opacity="0.95" />
                      <ellipse cx={x0 + rx * 0.08} cy={-ry * 0.14} rx={rx * 0.08} ry={rx * 0.1} fill="#fff" opacity="0.9" />
                      <path d={`M ${rx * 0.9} ${ry * 0.05} Q ${rx * 0.86} ${ry * 0.62} ${rx * 0.42} ${ry * 0.88}`} stroke="#ff7ad6" strokeWidth="4" fill="none" opacity="0.55" strokeLinecap="round" />
                      <path d={`M ${-rx * 0.88} ${-ry * 0.45} Q ${-rx * 0.97} ${ry * 0.1} ${-rx * 0.8} ${ry * 0.55}`} stroke="#ff7ad6" strokeWidth="3" fill="none" opacity="0.3" strokeLinecap="round" />
                    </g>
                  </g>
                );
              })}
            </g>
          </svg>
        </span>
      </span>
    </span>
  );
}
